import{_ as t,o,c as a,a3 as i}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"EloSync Mobile (tenant app)","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"EloSync Mobile (tenant app) | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/mobile-app"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"EloSync Mobile (tenant app) | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/mobile-app"}]]},"headers":[],"relativePath":"developer-guide/mobile-app.md","filePath":"developer-guide/mobile-app.md","lastUpdated":1787698014000}'),s={name:"developer-guide/mobile-app.md"};function d(n,e,l,r,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="elosync-mobile-tenant-app" tabindex="-1">EloSync Mobile (tenant app) <a class="header-anchor" href="#elosync-mobile-tenant-app" aria-label="Permalink to &quot;EloSync Mobile (tenant app)&quot;">​</a></h1><p>Official tenant workspace mobile client (<code>SaaS-Mobile</code> repo). <strong>Tenant API only</strong> â€” no Central admin surface.</p><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Choice</th></tr></thead><tbody><tr><td>Framework</td><td>Expo SDK 57 + React Native</td></tr><tr><td>Navigation</td><td>Expo Router</td></tr><tr><td>Dev workflow</td><td><strong>EAS development builds</strong> (<code>expo-dev-client</code>) â€” not App Store Expo Go</td></tr><tr><td>API</td><td>Axios â†’ <code>/api/tenant/v1</code></td></tr><tr><td>Auth</td><td>Laravel Sanctum Bearer tokens</td></tr><tr><td>Token storage</td><td><code>expo-secure-store</code></td></tr></tbody></table><p>App Store Expo Go remains on SDK 54; this project targets SDK 57. Use a <strong>development build</strong> or EAS <code>production</code>/<code>preview</code> binaries for devices.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPO_PUBLIC_API_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://api.example.com</span></span></code></pre></div><p>Tenant API base: <code>${EXPO_PUBLIC_API_URL}/api/tenant/v1</code></p><p>Native apps do not use browser CORS. Pin API TLS and rate limits on the backend as for any API client.</p><p>Physical devices cannot use <code>http://saas-backend.test</code> unless that host resolves on the phone â€” use a LAN IP or production API URL in <code>.env</code> / <code>eas.json</code> profiles.</p><h2 id="development-builds-eas" tabindex="-1">Development builds (EAS) <a class="header-anchor" href="#development-builds-eas" aria-label="Permalink to &quot;Development builds (EAS)&quot;">​</a></h2><p>Identifiers: iOS <code>com.diligentcreators.elosync</code>, Android <code>com.diligentcreators.elosync</code>, scheme <code>elosync</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:dev:android</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # internal APK</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:dev:ios</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # internal IPA (Apple Developer)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:dev:ios:simulator</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # iOS Simulator only</span></span></code></pre></div><p>After installing the dev client on a device:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:dev-client</span></span></code></pre></div><p>Open the <strong>EloSync</strong> dev build and scan the Metro QR code.</p><p>Rebuild when changing native modules, <code>app.json</code> plugins, or EAS native settings.</p><h3 id="eas-profiles" tabindex="-1">EAS profiles <a class="header-anchor" href="#eas-profiles" aria-label="Permalink to &quot;EAS profiles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Profile</th><th>Purpose</th></tr></thead><tbody><tr><td><code>development</code></td><td>Dev client, internal, physical devices</td></tr><tr><td><code>development-simulator</code></td><td>Dev client for iOS Simulator</td></tr><tr><td><code>preview</code></td><td>Internal release-like build</td></tr><tr><td><code>production</code></td><td>Store binaries (<code>npm run build:production</code>)</td></tr></tbody></table><p>Store submission: <code>eas submit</code> after a <code>production</code> build.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Mirrors the tenant web login (<code>SaaS-Frontend</code> <code>login-page.tsx</code> + <code>auth-store.ts</code>):</p><ol><li><code>POST /auth/login</code> with <code>email</code>, <code>password</code>, optional <code>remember</code>, optional <code>workspace</code> slug/domain, optional <code>latitude</code>/<code>longitude</code> (attendance check-in side-effect on the API).</li><li>Response: <code>token</code>, <code>user</code> (roles, permissions), <code>modules</code>, <code>workspace</code>.</li><li><code>GET /me</code> on cold start and after login to refresh session payload.</li><li><code>POST /me/logout</code> + clear SecureStore on sign out.</li><li>When <code>email_verified_at</code> is null, gate the app until verification (resend via <code>POST /me/email/verification-notification</code>).</li></ol><p>Workspace resolution (<code>InitializeTenancy</code> on the backend):</p><ul><li>Login can resolve tenant from <strong>email alone</strong> (tenant user emails are globally unique).</li><li>Optional <code>workspace</code> body or <code>X-Tenant-Domain</code> header disambiguates branding (<code>GET /public/settings</code>) and forgot-password flows.</li><li>After login, tenant context is carried by the Bearer token.</li></ul><p>Forgot password on mobile always includes <strong>workspace</strong> + email (the app is never host-bound like a workspace subdomain).</p><h2 id="authorization-gates" tabindex="-1">Authorization gates <a class="header-anchor" href="#authorization-gates" aria-label="Permalink to &quot;Authorization gates&quot;">​</a></h2><p>Reuse the web SPA model:</p><ul><li><strong>Modules:</strong> <code>user.modules</code> from login/<code>/me</code> â€” hide nav when module slug not entitled.</li><li><strong>Permissions:</strong> Spatie permission strings on <code>user.permissions</code>; <code>superadmin</code> role bypasses checks.</li></ul><h2 id="module-development" tabindex="-1">Module development <a class="header-anchor" href="#module-development" aria-label="Permalink to &quot;Module development&quot;">​</a></h2><p>New mobile module screens should mirror the <strong>Leads</strong> web module (list / create / view / edit) and gate by module + permission. Shared API contracts live in <code>SaaS-Docs/docs/api/</code>.</p><h2 id="store-release" tabindex="-1">Store release <a class="header-anchor" href="#store-release" aria-label="Permalink to &quot;Store release&quot;">​</a></h2><p>One multi-tenant binary (Play Store + App Store) via EAS <code>production</code> profile. Workspace users sign in with email â€” not per-customer white-label builds unless product adds that later.</p><h2 id="mobile-module-rollout" tabindex="-1">Mobile module rollout <a class="header-anchor" href="#mobile-module-rollout" aria-label="Permalink to &quot;Mobile module rollout&quot;">​</a></h2><p>Extend <code>config/modules.ts</code> and add <code>app/(app)/(tabs)/{slug}/</code> stack screens per module PR. Each PR should include:</p><ul><li>API service + types</li><li>List / create / view / edit (or justified subset)</li><li>Nav registration in <code>config/modules.ts</code> + tab visibility gates</li><li>User guide slice + changelog line</li></ul><p>Current shipped mobile modules: <strong>leads</strong>, <strong>tasks</strong>, <strong>notifications</strong> (shell), <strong>profile</strong>.</p><h3 id="leads-module-leads" tabindex="-1">Leads (<code>module:leads</code>) <a class="header-anchor" href="#leads-module-leads" aria-label="Permalink to &quot;Leads (`module:leads`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Piece</th><th>Location</th></tr></thead><tbody><tr><td>API client</td><td><code>lib/api/leads.ts</code> â€” <code>GET/POST /leads</code>, <code>GET/PUT/DELETE /leads/{id}</code>, <code>GET /lead-stages</code></td></tr><tr><td>Types</td><td><code>types/leads.ts</code> (re-exported from <code>types/api.ts</code>)</td></tr><tr><td>Routes</td><td><code>app/(app)/(tabs)/leads/</code> â€” <code>index</code> (list + search), <code>new</code>, <code>[id]/index</code> (view), <code>[id]/edit</code></td></tr><tr><td>Nav</td><td><code>config/modules.ts</code> â€” <code>permission: leads.view</code>, tab <code>/(app)/(tabs)/leads</code></td></tr><tr><td>Permissions</td><td><code>leads.view</code>, <code>leads.create</code>, <code>leads.update</code>, <code>leads.delete</code></td></tr></tbody></table><p>Tenant API reference: <a href="/api/tenant-v1-leads">Tenant API â€” Leads</a>.</p><h3 id="tasks-module-tasks" tabindex="-1">Tasks (<code>module:tasks</code>) <a class="header-anchor" href="#tasks-module-tasks" aria-label="Permalink to &quot;Tasks (`module:tasks`)&quot;">​</a></h3><p>Mirrors the Leads mobile pattern (list / create / view / edit stack, React Query, permission gates).</p><table tabindex="0"><thead><tr><th>Piece</th><th>Location</th></tr></thead><tbody><tr><td>API client</td><td><code>lib/api/tasks.ts</code> â€” <code>GET/POST /tasks</code>, <code>GET/PUT/DELETE /tasks/{id}</code>, <code>POST /tasks/{id}/complete</code>, <code>POST /tasks/{id}/reopen</code></td></tr><tr><td>Types</td><td><code>types/tasks.ts</code> (re-exported from <code>types/api.ts</code>)</td></tr><tr><td>Routes</td><td><code>app/(app)/(tabs)/tasks/</code> â€” <code>index</code> (list + search), <code>new</code>, <code>[id]/index</code> (view + complete/reopen), <code>[id]/edit</code></td></tr><tr><td>Nav</td><td><code>config/modules.ts</code> â€” <code>permission: tasks.view</code>, tab <code>/(app)/(tabs)/tasks</code></td></tr><tr><td>Permissions</td><td><code>tasks.view</code>, <code>tasks.create</code>, <code>tasks.update</code>, <code>tasks.delete</code>, <code>tasks.complete</code></td></tr></tbody></table><p>Tenant API reference: <a href="/api/tenant-v1-tasks">Tenant API â€” Tasks</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/api/index">Tenant API index</a></li><li><a href="/developer-guide/module-development-guide">Module development (web blueprint)</a></li><li><a href="/getting-started/platform-freeze">Platform freeze</a></li></ul>',46)])])}const m=t(s,[["render",d]]);export{u as __pageData,m as default};
